pub fn same_content_at(&self, a: &str, b: &str, pathspecs: &[PathBuf]) -> Result<bool, VcsError> {
    let mut args: Vec<String> = ["diff", "--quiet", "--no-ext-diff", a, b, "--"]
        .map(str::to_owned)
        .into();
    args.extend(pathspecs.iter().map(|path| path.to_string_lossy().into_owned()));

