impl GroupTable {
    pub(crate) fn validate_syntactic(raw: &RawGroupTable) -> Result<(), ConfigError> {
        let members = |groups: &'_ [RawGroup]| -> Vec<(GroupName, Vec<String>)> {
            groups.iter().map(|g| (g.name.clone(), g.members.clone())).collect()
