        Ok(Self::failure())
    }
    fn run_with_timeout(
        &self,
        _program: &str,
        _args: &[&str],
        _cwd: &Path,
        _timeout: std::time::Duration,
    ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
        self.used_live_echo.store(true, std::sync::atomic::Ordering::SeqCst);
        Ok(Self::failure())
    }
    fn run_quiet(
        &self,
        _program: &str,
        _args: &[&str],
