//! Standalone callisto CLI binary library target.

#![allow(clippy::result_large_err)]

pub mod cli;
pub mod color;
pub mod commands;
pub mod error;
pub mod output;
pub mod render;
pub mod runner;
pub mod tty;
pub mod workspace;

pub use cli::{Cli, Command, GlobalArgs, OutputFormat};
pub use error::{format_error_json, CliError};
pub use output::{log_line, write_json};
pub use runner::CliCommandRunner;

#![allow(clippy::result_large_err)]

use std::process::ExitCode;

use clap::Parser;

use callisto_cli::cli::{Cli, Command};
use callisto_cli::commands::*;

// Exit code contract for every subcommand
// =========================================
//
// Default rule: every `Err(CliError)` arm below maps to exit code 1 (FAILURE).
// `Ok(code)` is returned verbatim, so each handler owns its own success codes.
//
//   add            0 on success (changeset written or dry-run preview)
//                  1 on any error (NotATty, invalid package spec, I/O, etc.)
//
//   status         0 when --check is not set (always, regardless of diagnostics --
//                    status without --check is informational, never a gate), or
//                    when --check is set and there are no Error-severity diagnostics
//                    (or Warning under --strict), regardless of pending changesets
//                  1 when --check is set and any diagnostic is Error-severity (or
//                    Warning under --strict), regardless of pending changesets
//                  (pending state never affects the exit code: read `pending` from
//                  `--format json`, or the printed count in text output)
//
//   matrix         0 on success (report printed, including an empty report or
//                  one carrying UnrecognisedPlatformTriple warnings)
//                  1 on any error (unknown --package, malformed/wrong-type
//                  manifest, conflicting platform-target sources)
//
//   version        0 on success (versions bumped or dry-run preview)
//                  1 on any error (graph error, strict violation, etc.)
//
//   pre            0 on success
//                  1 on any error
//
//   snapshot       0 on success (snapshot versions applied or dry-run preview)
//                  1 on any error (graph error, Error-severity graph diagnostics
//                  under --strict, etc.)
//
//   init           0 on success (configuration scaffolded or dry-run preview)
//                  1 on any error
//
//   compose-pr-body  0 on success
//                    1 on any error
//
//   release        0 on success, including `Nothing to release.` and --dry-run
//                  1 on any error (dirty worktree, missing credential, CI-only workspace, etc.)
//
//   completions    0 on success
//                  1 on any error
//
//   schema         0 on success
//                  1 on any error

fn main() -> ExitCode {
    let cli = Cli::parse();
    let command_name = cli.command.name();

    let res = match cli.command {
        Command::Add(args) => add::handle(args, &cli.global),
        Command::Status(args) => status::handle(args, &cli.global),
        Command::Matrix(args) => matrix::handle(args, &cli.global),
        Command::Version(args) => version::handle(args, &cli.global),
        Command::Pre(args) => pre::handle(args, &cli.global),
        Command::Snapshot(args) => snapshot::handle(args, &cli.global),
        Command::Init(args) => init::handle(args, &cli.global),
        Command::ComposePrBody(args) => compose_pr_body::handle(args, &cli.global),
        Command::Release(args) => release::handle(args, &cli.global),
        Command::ReleasePr(args) => release_pr::handle(args, &cli.global),
        Command::Completions(args) => completions::handle(args, &cli.global),
        Command::Schema(args) => schema::handle(args, &cli.global),
        Command::Help(args) => help::handle(args, &cli.global),
    };

    match res {
        Ok(code) => code,
        Err(err) => {
            if cli.global.format == callisto_cli::cli::OutputFormat::Json {
                let report = callisto_cli::error::format_error_json(command_name, &err);
                let _res = callisto_cli::output::write_json(&mut std::io::stderr(), &report);
            } else {
                let indeterminate = matches!(
                    miette::Diagnostic::code(&err).map(|code| code.to_string()).as_deref(),
                    Some("E157" | "E176")
                );
                eprintln!("{:?}", miette::Report::new(err));
                if let Some(summary) = indeterminate.then(callisto_cli::runner::last_failed_command).flatten() {
                    eprintln!("Most recent failed command (redacted):\n{summary}");
                }
            }
            ExitCode::FAILURE
        }
    }
}

